import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type MonthlyFlipBoardProps = Record<string, any>;

const Hinge: React.FC<{ left: boolean }> = ({ left }) => (
  <div
    style={{
      position: "absolute",
      top: "50%",
      left: left ? -16 : "auto",
      right: !left ? -16 : "auto",
      width: 32,
      height: 64,
      backgroundColor: "#222",
      borderRadius: 8,
      transform: "translateY(-50%)",
      zIndex: 10,
      boxShadow: "inset 0 0 10px rgba(0,0,0,0.8), 0 10px 20px rgba(0,0,0,0.6)",
      border: "1px solid #333",
    }}
  >
    <div
      style={{
        position: "absolute",
        top: "50%",
        left: left ? "100%" : 0,
        width: 16,
        height: 6,
        backgroundColor: "#555",
        transform: "translate(-50%, -50%)",
        zIndex: -1,
        boxShadow: "0 2px 4px rgba(0,0,0,0.5)",
      }}
    />
  </div>
);

const HalfCard: React.FC<{
  text: string;
  type: "top" | "bottom";
  rotationX: number;
  zIndex: number;
  cardColor: string;
  textGradientStart: string;
  textGradientEnd: string;
  cardWidth: number;
  cardHeight: number;
  shadowOpacity: number;
}> = ({
  text,
  type,
  rotationX,
  zIndex,
  cardColor,
  textGradientStart,
  textGradientEnd,
  cardWidth,
  cardHeight,
  shadowOpacity,
}) => {
  const isTop = type === "top";
  const gap = 3;

  return (
    <div
      style={{
        position: "absolute",
        width: cardWidth,
        height: cardHeight / 2 - gap,
        top: isTop ? 0 : cardHeight / 2 + gap,
        left: "50%",
        marginLeft: -cardWidth / 2,
        overflow: "hidden",
        transformOrigin: isTop ? "bottom center" : "top center",
        transform: `perspective(1200px) rotateX(${rotationX}deg)`,
        zIndex,
        backgroundColor: cardColor,
        borderRadius: isTop ? "40px 40px 0 0" : "0 0 40px 40px",
        borderBottom: isTop ? "1px solid rgba(0,0,0,0.1)" : "none",
        borderTop: !isTop ? "1px solid rgba(0,0,0,0.1)" : "none",
        boxShadow: isTop
          ? "inset 0 -10px 30px rgba(0,0,0,0.05), 0 5px 25px rgba(0,0,0,0.15)"
          : "inset 0 10px 30px rgba(0,0,0,0.05), 0 15px 35px rgba(0,0,0,0.2)",
        backfaceVisibility: "hidden",
        WebkitBackfaceVisibility: "hidden",
        transition: "none",
      }}
    >
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: cardHeight,
          top: isTop ? 0 : -(cardHeight / 2 + gap),
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          fontSize: cardHeight * 0.45,
          fontFamily: "Montserrat",
          fontWeight: 800,
          background: `linear-gradient(to bottom, ${textGradientStart} 10%, ${textGradientEnd} 90%)`,
          WebkitBackgroundClip: "text",
          WebkitTextFillColor: "transparent",
          color: "transparent",
          letterSpacing: "-0.03em",
          transition: "none",
        }}
      >
        {text}
      </div>
      <div
        style={{
          position: "absolute",
          inset: 0,
          backgroundColor: "black",
          opacity: shadowOpacity,
          pointerEvents: "none",
          transition: "none",
        }}
      />
    </div>
  );
};

const MonthlyFlipBoard: React.FC<MonthlyFlipBoardProps> = ({
  backgroundColor = "#0d0d0d",
  transparentBackground = false,
  durationInSeconds = 12,
  months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
  cardColor = "#F9F9F9",
  textGradientStart = "#780000",
  textGradientEnd = "#c1121f",
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Responsive sizing
  const s = Math.min(width, height);
  const cardWidth = s * 0.8;
  const cardHeight = s * 0.8;

  // Animation Sequence Logic
  const validMonths = months.length > 0 ? months : ["Jan"];
  const framesPerSegment = Math.max(1, Math.floor((durationInSeconds * fps) / validMonths.length));
  
  const currentIndex = Math.floor(frame / framesPerSegment) % validMonths.length;
  const nextIndex = (currentIndex + 1) % validMonths.length;
  
  const segmentFrame = frame % framesPerSegment;
  const flipStartFrame = framesPerSegment * 0.5;

  // Spring animation for the flip (0 to 1)
  const flipProgress = spring({
    frame: segmentFrame - flipStartFrame,
    fps,
    config: { damping: 13, stiffness: 140, mass: 0.8 },
  });

  // Calculate rotations
  const topRotation = interpolate(flipProgress, [0, 0.5], [0, -90], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomRotation = interpolate(flipProgress, [0.5, 1], [90, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "extend", // Extend allows the slight bounce effect on landing
  });

  // Calculate shadows
  const bottomStaticShadow = interpolate(flipProgress, [0, 0.5, 1], [0, 0.6, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  
  const topFlapShadow = interpolate(flipProgress, [0, 0.5], [0, 0.5], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomFlapShadow = interpolate(flipProgress, [0.5, 1], [0.5, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {!transparentBackground && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            width: width * 1.5,
            height: height * 1.5,
            transform: "translate(-50%, -50%)",
            background: "radial-gradient(circle at 50% 50%, rgba(255,255,255,0.03) 0%, rgba(255,255,255,0) 60%)",
            transition: "none",
          }}
        />
      )}

      <div
        style={{
          position: "absolute",
          top: "50%",
          left: "50%",
          width: cardWidth,
          height: cardHeight,
          transform: "translate(-50%, -50%)",
          transition: "none",
        }}
      >
        {/* Dark core behind the split gap */}
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: 0,
            width: "100%",
            height: 20,
            backgroundColor: "#050505",
            transform: "translateY(-50%)",
            zIndex: 0,
            borderRadius: 10,
            boxShadow: "inset 0 5px 10px rgba(0,0,0,0.5)",
          }}
        />

        {/* Static Background Cards */}
        <HalfCard
          text={validMonths[nextIndex]}
          type="top"
          rotationX={0}
          zIndex={1}
          cardColor={cardColor}
          textGradientStart={textGradientStart}
          textGradientEnd={textGradientEnd}
          cardWidth={cardWidth}
          cardHeight={cardHeight}
          shadowOpacity={0}
        />
        <HalfCard
          text={validMonths[currentIndex]}
          type="bottom"
          rotationX={0}
          zIndex={1}
          cardColor={cardColor}
          textGradientStart={textGradientStart}
          textGradientEnd={textGradientEnd}
          cardWidth={cardWidth}
          cardHeight={cardHeight}
          shadowOpacity={bottomStaticShadow}
        />

        {/* Animated Flaps */}
        <HalfCard
          text={validMonths[currentIndex]}
          type="top"
          rotationX={topRotation}
          zIndex={2}
          cardColor={cardColor}
          textGradientStart={textGradientStart}
          textGradientEnd={textGradientEnd}
          cardWidth={cardWidth}
          cardHeight={cardHeight}
          shadowOpacity={topFlapShadow}
        />
        <HalfCard
          text={validMonths[nextIndex]}
          type="bottom"
          rotationX={bottomRotation}
          zIndex={3}
          cardColor={cardColor}
          textGradientStart={textGradientStart}
          textGradientEnd={textGradientEnd}
          cardWidth={cardWidth}
          cardHeight={cardHeight}
          shadowOpacity={bottomFlapShadow}
        />

        {/* Side Hinges */}
        <Hinge left />
        <Hinge left={false} />
      </div>
    </AbsoluteFill>
  );
};

export default MonthlyFlipBoard;